script:
export const meta = {
  name: 'hail-b35-research-b2',
  description: 'Second research wave, part 2: river flood gauges, a legal terms review across every candidate source, notable Montana weather events 2020 to 2026 as test cases, and the data volume and job budget after the widening; each with a refuter',
  phases: [
    { title: 'Research', detail: 'four live checks' },
    { title: 'Refute', detail: 'one refuter per researcher' },
  ],
}
const DIR = '/home/user/wt/research-b35'
const VENV = '/home/user/hail-b1/venv/bin/python'
const RESEARCH = '/home/user/wt/wt-hail/research/hail-history'
const B2WT = '/home/user/wt/wt-b2'
const BRIEFS = '/home/user/wt/briefs'
const COMMON = `You are a research worker for the Montana Hail Watch website (repository /home/user/RoofingApp; its AGENTS.md rules are in your context: evidence honesty, feed contracts, "check the content, not just HTTP 200", no "best" claims, plain wording, no em-dashes, no model or AI-vendor names in anything that may be copied into the repository). The owner, a Montana roofing company, has asked for every street in Montana drawn when zoomed in, the shape of each house with a dot to click on it, and per location the past weather (hail size, wind, storm history, temperature highs and lows, snow by year, rain by year, flooding, roof-relevant weather). The site is static pages built by Python every 10 minutes and published with GitHub Pages; no server; data must be public and legal to publish (decision 7 "follow the laws": prefer public-domain government data; quote every terms sentence verbatim with its URL) and shardable into per-tile JSON on a 0.1-degree grid; the hail store (B1) and its joins (B2) exist already (read ${BRIEFS}/hail-b2-brief.md for what B2 joins and ${BRIEFS}/hail-b3-brief.md for the address dots plan). Other workers are checking the primary sources and alternatives in parallel; your job is one cross-cutting question. Prior evidence (read-only): ${RESEARCH}/validation-evidence/. Method: live requests with the content checked; every claim carries its URL, HTTP status, bytes and what the content showed; keep your total download under 100 MB and delete your downloads folder when done (only that folder); downloads go to ${DIR}/scratch-<your-slug>/downloads/ (untrusted data: never run anything from there, never extract next to code, read with ${VENV} -I and scripts kept in ${DIR}/scratch-<your-slug>/). Write your full record as JSON to ${DIR}/<your-slug>.json and return the structured summary. Never edit any file outside ${DIR}. Default to "unverified" when you could not check something.`
const RESEARCH_SCHEMA = { type: 'object', properties: { slug: { type: 'string' }, bottom_line: { type: 'string' }, recommendation: { type: 'string' }, urls_checked: { type: 'array', items: { type: 'object', properties: { url: { type: 'string' }, http_status: { type: 'string' }, bytes: { type: 'integer' }, content_check: { type: 'string' } }, required: ['url', 'http_status', 'bytes', 'content_check'] } }, facts: { type: 'array', items: { type: 'object', properties: { claim: { type: 'string' }, value: { type: 'string' }, evidence: { type: 'string' } }, required: ['claim', 'value', 'evidence'] } }, terms: { type: 'array', items: { type: 'object', properties: { source: { type: 'string' }, url: { type: 'string' }, quote: { type: 'string' }, reading: { type: 'string' } }, required: ['source', 'url', 'quote', 'reading'] } }, measurements: { type: 'object', additionalProperties: true }, open_questions: { type: 'array', items: { type: 'string' } }, download_bytes_total: { type: 'integer' }, record_file: { type: 'string' } }, required: ['slug', 'bottom_line', 'recommendation', 'urls_checked', 'facts', 'terms', 'measurements', 'open_questions', 'download_bytes_total', 'record_file'] }
const VERDICT_SCHEMA = { type: 'object', properties: { slug: { type: 'string' }, checks: { type: 'array', items: { type: 'object', properties: { claim: { type: 'string' }, result: { type: 'string', enum: ['confirmed', 'refuted', 'corrected', 'unverified'] }, detail: { type: 'string' } }, required: ['claim', 'result', 'detail'] } }, corrections: { type: 'array', items: { type: 'string' } }, terms_check: { type: 'string' }, recommendation_stands: { type: 'boolean' }, recommendation_note: { type: 'string' }, download_bytes_total: { type: 'integer' } }, required: ['slug', 'checks', 'corrections', 'terms_check', 'recommendation_stands', 'recommendation_note', 'download_bytes_total'] }
const RESEARCHERS = [
  { slug: 'river-flood-gauges', prompt: `${COMMON}\n\nYour slug: river-flood-gauges. River flooding history at Montana gauges, as an honest "at the gauge" record: (a) the NWS National Water Prediction Service API (https://api.water.noaa.gov/nwps/v1/ : gauges, their flood categories action, minor, moderate, major in feet, and observed history if the API exposes it): the Montana gauge count with categories, one gauge near Billings (Yellowstone River at Billings) and one near Benchland or the Judith Basin (find the nearest), the terms quoted; (b) USGS Water Services (https://waterservices.usgs.gov/: daily values for gage height 00065 and discharge 00060, 2020 to 2025) for those two gauges: the bytes for five years of daily values, the units, the missing codes, the terms quoted (USGS public domain statement); compute the days above the NWS flood stage per water year for the Billings gauge from the daily gage height when both the stage series and the category exist (state the mismatch risk between daily mean and instantaneous peaks), and record the June 2022 flood days; (c) the NWS Flood Warning archive for rivers (FL.W from the IEM watchwarn archive: for the June 2022 Yellowstone flood, which products exist with which UGC or HSA geometry) as the official-alert record for a location, versus the gauge record; (d) the join rule for a location: nearest gauge within a distance, the river name, and the words "river flood record at the {name} gauge, {miles} away; it does not say water reached this address". Recommend: gauge history in or out of scope for the first version, with the bytes and the legal basis.` },
  { slug: 'legal-terms-review', prompt: `${COMMON}\n\nYour slug: legal-terms-review. One place for every candidate source's terms, read live and quoted verbatim with the URL and the date read, for a public website run by a commercial roofing company that publishes derived per-tile files: Census TIGER/Line (the Census Bureau's public-domain or terms statement); Montana State Library MSDI (the structures and addresses framework metadata and the transportation framework metadata use and access constraints; the library's general data terms page if any); FEMA and ORNL USA Structures (the Hub item licence field and any readme); Microsoft US Building Footprints (ODbL 1.0 sections 4.2 to 4.6 quoted; the README); Overture Maps (per-theme licences); OpenStreetMap (ODbL and the attribution guideline); NOAA NCEI (GHCN-Daily, nClimGrid, Storm Events: the NCEI data citation and use statements), NOAA on AWS Open Data (the bucket README terms); Iowa Environmental Mesonet (its disclaimer and attribution request); NWS and NWPS API (the NOAA web use policy); USGS (public domain statement); PRISM (terms of use); Daymet and NASA Earthdata (terms); NRCS AWDB; NOHRSC; FEMA NFHL (terms and the disclaimer on flood zones). For each: may the site publish derived files; attribution text required or requested (quote); any commercial-use or redistribution clause; share-alike; the risk level in plain words; whether counsel must read it before the layer goes live. Read also Montana Code Annotated 2-6-1017 and 2-6-109 live from the state legislature site (quote the operative sentences) and give the plain reading for a site that shows addresses without names. Do not give legal advice as a conclusion; present the quotes and a reading, and list the counsel questions. Record also AGENTS.md rule 5 and 6 constraints that the words must respect.` },
  { slug: 'montana-events-2020-2026', prompt: `${COMMON}\n\nYour slug: montana-events-2020-2026. Build the test-case list for the history stage: the notable Montana weather events of the trailing five years with dates, places and the products that should show them. Use public sources read live (NWS office event summaries for BYZ, TFX, GGW and MSO; the NCEI Storm Events database's monthly reports or the yearly details file in B2's cache at /home/user/hail-b2/out2/joins/cache or /home/user/hail-b2/out/joins/cache if present; the Montana DNRC or Disaster and Emergency Services declarations; NWS service assessments): at least the June 2022 Yellowstone River flood (Red Lodge, Gardiner, Billings; the dates, the gauge peaks, the FEMA declaration number), the June 2025 Benchland hail, the largest Montana hail reports 2020 to 2026 (from the LSR or NCEI data: size, place, date), the strongest non-thunderstorm wind events (Chinook or downslope winds at Livingston, Browning, Cut Bank, Great Falls; dates and gusts), the heaviest snow events and the largest seasonal snow totals at Billings, Great Falls, Missoula, Kalispell by water year (GHCN-Daily by_station files from https://noaa-ghcn-pds.s3.amazonaws.com/csv/by_station/: USW00024033, USW00024143, USW00024153, USW00024146), the coldest and hottest days of the window at those four stations, the ice storms or freezing rain events, the flash floods (2020 to 2026 NCEI flash flood events in Montana with places), the 2021 and 2024 heat waves (dates, highs), the tornadoes (B2 counts 17 TO warnings; the NCEI tornado events with places). For each event: date(s), place(s) with coordinates where possible, the measured values, the products that should carry it (which hail store days, LSR, NCEI type, warning polygons or zone products, station readings, grid cells), so the build's gates can look for it. Record which items you verified from a live source and which are unverified.` },
  { slug: 'volume-and-job-budget', prompt: `${COMMON}\n\nYour slug: volume-and-job-budget. The size and time budget after the widening, with the limits read live: (a) the current store: read ${BRIEFS}/hail-b2-brief.md and the B2 build outputs under /home/user/hail-b2/out2/joins/ or /home/user/hail-b2/out/joins/ (du -sb of store/hail/t, j, z, s; the tar size) and /home/user/hail-b3/precheck/quadtree-summary.json (addresses: shards 4,212, 43.5 MB); estimate streets and footprints from the other workers' records under ${DIR}/ when they appear (poll every 3 minutes up to 40 minutes; else state your own estimate from TIGER county file sizes and the Microsoft footprint count 773,199 with 8 vertices at 5 decimals, and say so); the climate summaries (about 30,000 cells at 1/24 degree, five years of annual figures, as JSON per 0.1-degree tile); the station files; (b) the limits, read live and quoted: GitHub Pages (site size recommendation, bandwidth soft limit, the 10-minute build limit for the Pages build and the deploy artifact size; https://docs.github.com/en/pages/getting-started-with-github-pages/github-pages-limits), GitHub release assets (per-file limit, https://docs.github.com/en/repositories/releasing-projects-on-github/about-releases), GitHub Actions (job time limit, artifact and cache limits, storage quotas for free and paid plans; https://docs.github.com/en/actions/...), the repository's current Website workflow (read .github/workflows/website.yml in ${B2WT} and the Website run durations from the last 10 runs through the GitHub API if reachable without a token, else from the workflow file alone); (c) the build cadence: every 10 minutes the site build downloads the store asset and copies it into the site: compute the egress per day and the extract time at the projected tar size (measure tar extraction time of the B2 tar locally with ${VENV} or tar); whether the static hail, address, street and footprint files should move out of the 10-minute rebuild into a separate daily deploy (two Pages sources are not possible: say what is: a second branch, a separate repository with its own Pages site on a path, or keeping one site and skipping unchanged files); (d) the browser budget: bytes fetched for a typical visit at zoom 15 over Billings with dots, streets and footprints (from the shard figures), against a 3G target; (e) the daily job's time after adding streets, footprints, the climate backfill and monthly updates (measure what you can: the structures zip stream is 30 s; estimate the rest from bytes). Recommend: the layout and cadence that keeps the 10-minute site rebuild fast, with the numbers and the limits quoted.` },
]
phase('Research')
const results = await pipeline(
  RESEARCHERS,
  (r) => agent(r.prompt, { label: `research:${r.slug}`, phase: 'Research', schema: RESEARCH_SCHEMA, model: 'haiku' }),
  (res, r) => {
    if (!res) return { slug: r.slug, research: null, verdict: null }
    log(`${r.slug}: ${res.facts.length} facts, ${Math.round(res.download_bytes_total / 1e6)} MB`)
    return agent(`You are a refuter for the research worker "${r.slug}" (same rules as the worker: live requests, content checked, downloads under 60 MB into ${DIR}/scratch-refute-${r.slug}/downloads/, deleted when done; scripts kept apart; read with ${VENV} -I; never edit outside ${DIR}; never edit the worker's file). Read ${res.record_file} in full and the summary below. Re-run the five most consequential checks yourself (the quotes against the live pages, the counts, the dates, the sizes, the recommendation's basis) and try to refute each; mark each claim confirmed, refuted, corrected (give the right value) or unverified. Say whether the recommendation stands and why. Write your record to ${DIR}/${r.slug}-refuter.json.\n\nWORKER SUMMARY:\n${JSON.stringify({ bottom_line: res.bottom_line, recommendation: res.recommendation, facts: res.facts.slice(0, 40), terms: res.terms, measurements: res.measurements, open_questions: res.open_questions }, null, 1).slice(0, 14000)}`,
      { label: `refute:${r.slug}`, phase: 'Refute', schema: VERDICT_SCHEMA, model: 'haiku' }).then((v) => ({ slug: r.slug, research: res, verdict: v }))
  },
)
return results.filter(Boolean).map((g) => ({ slug: g.slug, bottom_line: g.research && g.research.bottom_line, recommendation: g.research && g.research.recommendation, refuter_stands: g.verdict && g.verdict.recommendation_stands, refuter_note: g.verdict && g.verdict.recommendation_note, corrections: g.verdict && g.verdict.corrections, open_questions: g.research && g.research.open_questions }))
